'use strict';
const KEY='adsp-study-v1';
let lessons=[],questions=[];
function fresh(){return {version:1,completed:[],lesson:0,answers:{},wrong:[],resolved:[],quizIndex:0};}
function sanitize(value){const s=fresh();if(!value||value.version!==1)return s;s.completed=[...new Set((Array.isArray(value.completed)?value.completed:[]).filter(n=>Number.isInteger(n)&&n>=0&&n<lessons.length))];s.lesson=Number.isInteger(value.lesson)&&value.lesson>=0&&value.lesson<lessons.length?value.lesson:0;s.quizIndex=Number.isInteger(value.quizIndex)&&value.quizIndex>=0&&value.quizIndex<questions.length?value.quizIndex:0;for(const q of questions){const a=value.answers?.[q.id];if(Number.isInteger(a)&&a>=0&&a<4)s.answers[q.id]=a;}s.wrong=questions.filter(q=>q.id in s.answers&&s.answers[q.id]!==q.answer).map(q=>q.id);s.resolved=(Array.isArray(value.resolved)?value.resolved:[]).filter(id=>s.wrong.includes(id));if(Array.isArray(value.completedIds))s.completed=[...new Set(value.completedIds.map(id=>lessons.findIndex(l=>l.id===id)).filter(i=>i>=0))];if(value.lessonId){const i=lessons.findIndex(l=>l.id===value.lessonId);if(i>=0)s.lesson=i;}if(value.questionId){const i=questions.findIndex(q=>q.id===value.questionId);if(i>=0)s.quizIndex=i;}return s;}
let storageOK=true,state=fresh();
let selected=null,reviewId=null,reviewResult=null,quizSummary=false;
const main=document.getElementById('main');
function progressSnapshot(){return {...state,completedIds:state.completed.map(i=>lessons[i].id),lessonId:lessons[state.lesson]?.id,questionId:questions[state.quizIndex]?.id};}
function persist(){if(window.StudyAuth?.user){window.StudyAuth.save(progressSnapshot());return;}try{localStorage.setItem(KEY,JSON.stringify(progressSnapshot()));storageOK=true;}catch{storageOK=false;}updateSaveStatus();}
function updateSaveStatus(){if(window.StudyAuth?.user){window.StudyAuth.status();return;}document.getElementById('save-status').textContent=storageOK?'● 게스트 · 이 브라우저에 저장':'저장 불가 · 현재 탭에서만 유지';}
function pending(){return state.wrong.filter(id=>!state.resolved.includes(id));}
function answered(){return Object.keys(state.answers).length;}
function correct(){return questions.filter(q=>state.answers[q.id]===q.answer).length;}
function progress(){return Math.round((state.completed.length+answered()+state.resolved.length)/(lessons.length+questions.length+state.wrong.length)*100);}
function heading(title,desc){return `<div class="intro"><div><div class="eyebrow">YOUR DAILY STUDY, ONE STEP CLOSER</div><h1>${title}</h1><p>${desc}</p></div><span class="date">${new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'short'})}</span></div>`;}
function home(){return heading('오늘도, 합격에 한 걸음 더.','조금씩 쌓아가는 실력. 오늘의 학습을 시작해 보세요.')+`<section class="hero"><div><span class="tag">1과목 · 데이터 이해</span><h2>모든 분석의 시작,<br>데이터와 정보 이해하기</h2><p>데이터의 유형부터 DIKW 피라미드까지.<br>핵심 개념을 익히고 ${questions.length}개의 문제로 이해도를 확인하세요.</p><a class="btn" href="#learn">${state.completed.length?'이어서 학습하기':'오늘의 학습 시작'} <span>→</span></a></div><div class="hero-art" aria-hidden="true"><span class="spark">✳</span><div class="book">THE FIRST STEP<strong>DATA<br>& INFO</strong>01 ───</div></div></section><section class="stats" aria-label="학습 통계"><div class="stat"><div class="stat-label">단원 학습 진도 <span>◴</span></div><strong>${progress()}<small>%</small></strong><div class="bar"><i style="width:${progress()}%"></i></div><div class="stat-foot">개념 · 문제 · 오답 복습 반영</div></div><div class="stat"><div class="stat-label">풀이한 문제 <span>▤</span></div><strong>${answered()}<small>/ ${questions.length}문제</small></strong><div class="stat-foot">배운 내용을 문제로 확인해요</div></div><div class="stat"><div class="stat-label">첫 풀이 정답률 <span>◎</span></div><strong>${answered()?Math.round(correct()/answered()*100):0}<small>%</small></strong><div class="stat-foot">${answered()?`${answered()}문제 중 ${correct()}문제 정답`:'첫 문제를 풀면 기록이 시작돼요'}</div></div></section><div class="columns"><section><div class="section-title"><h2>나의 학습 로드맵</h2><span>STEP BY STEP</span></div><div class="panel"><div class="chapter-top"><span class="chapter-icon">▤</span><div><small>CHAPTER 01</small><h3>데이터와 정보</h3></div><span class="pill" style="margin-left:auto">${progress()===100?'학습 완료':'학습 중'}</span></div>${step(1,'핵심 개념 학습',`개념 카드 ${state.completed.length} / ${lessons.length}개 완료`,'learn',state.completed.length===lessons.length)}${step(2,'단원 확인 문제',`예상 문제 ${answered()} / ${questions.length}개 풀이`,'quiz',answered()===questions.length)}${step(3,'오답 다시 풀기',pending().length?`${pending().length}문제 복습 대기`:answered()===questions.length?'복습할 오답이 없습니다':'문제를 풀면 오답이 모여요','review',answered()===questions.length&&!pending().length)}<div class="tip">✦ &nbsp;개념을 이해한 뒤 바로 문제를 풀면 더 오래 기억할 수 있어요.</div></div></section><section><div class="section-title"><h2>잊기 전에, 한 번 더</h2><span>REVIEW</span></div><div class="panel review-box"><span class="pill">나의 오답 노트</span><div class="count">${pending().length}<small style="font-size:12px;margin-left:6px">문제</small></div><h3>${pending().length?'틀린 문제는 성장의 힌트예요.':'차근차근 실력을 쌓아가요.'}</h3><p>${pending().length?'해설을 읽고 다시 풀어보세요.<br>맞힌 문제는 복습 완료로 기록돼요.':'틀린 문제는 자동으로 모아드릴게요.<br>복습까지 마치면 단원 진도가 완성돼요.'}</p><a class="btn secondary" href="#review">오답 노트 열기 <span>→</span></a></div><p class="note">ⓘ 학습 기록은 현재 기기와 브라우저에 저장됩니다.<br>브라우저 데이터를 삭제하면 기록도 지워집니다.</p></section></div>`;}
function step(n,title,sub,route,done){return `<div class="step ${done?'done':''}"><span class="step-num">${done?'✓':n}</span><div>${title}<small>${sub}</small></div><a href="#${route}">${done?'다시 보기':'시작하기'} →</a></div>`;}
function learn(){const i=state.lesson;return heading('개념을 차근차근, 확실하게.','1과목 데이터 이해 / 01 데이터와 정보')+`<div class="lesson-tabs" role="group" aria-label="개념 선택">${lessons.map((l,n)=>`<button class="${n===i?'active':''}" data-lesson="${n}">${state.completed.includes(n)?'✓':`0${n+1}`} ${l.title.split(':')[0]}</button>`).join('')}</div><article class="panel article"><span class="eyebrow">CONCEPT 0${i+1} / ${String(lessons.length).padStart(2,'0')}</span><h2>${lessons[i].title}</h2>${lessons[i].body}<div class="actions"><button class="btn secondary" data-action="prev" ${i===0?'disabled':''}>← 이전 개념</button><button class="btn" data-action="complete">${state.completed.includes(i)?'학습 완료 ✓ · ':''}${i===lessons.length-1?'완료하고 문제 풀기 →':'완료하고 다음 개념 →'}</button></div></article>`;}
function questionCard(q,mode){const isReview=mode==='review',a=isReview?reviewResult:state.answers[q.id],submitted=Number.isInteger(a);return `<section class="panel question"><div class="section-title"><span class="pill">${lessons[q.lesson].title}</span><span>${isReview?'오답 재풀이':`QUESTION ${state.quizIndex+1} / ${questions.length}`}</span></div>${!isReview?`<div class="bar"><i style="width:${answered()/questions.length*100}%"></i></div>`:''}<h2>${q.text}</h2><div class="options" role="group" aria-label="답안 선택">${q.options.map((o,n)=>`<button class="option ${submitted?(n===q.answer?'correct':n===a?'incorrect':''):selected===n?'selected':''}" data-choice="${n}" aria-pressed="${selected===n||a===n}" ${submitted?'disabled':''}><span>${n+1}</span>${o}${submitted&&n===q.answer?' ✓':''}</button>`).join('')}</div>${submitted?`<div class="feedback ${a!==q.answer?'wrong':''}" role="status"><strong>${a===q.answer?'정답입니다!':`아쉬워요. 정답은 ${q.answer+1}번입니다.`}</strong><p>${q.explanation}</p><button class="btn secondary" data-concept="${q.lesson}" style="margin-top:12px">관련 개념 다시 보기 ↗</button></div>`:''}<div class="actions">${isReview?'<button class="btn secondary" data-action="review-list">목록으로</button>':`<button class="btn secondary" data-action="previous-question" ${state.quizIndex===0?'disabled':''}>← 이전 문제</button>`}${submitted?`<button class="btn" data-action="${isReview?'review-list':'next'}">${isReview?(a===q.answer?'복습 완료 · 목록으로':'목록에서 다시 도전'):(state.quizIndex===questions.length-1?'학습 결과 보기':'다음 문제 →')}</button>`:`<button class="btn" data-action="${isReview?'review-submit':'submit'}" ${selected===null?'disabled':''}>정답 확인</button>`}</div></section>`;}
function quiz(){if(quizSummary)return heading('한 번 더 이해한 만큼, 앞으로.','단원 확인 문제 학습 결과')+`<section class="panel empty"><span class="eyebrow">CHAPTER 01 · RESULT</span><h2>데이터와 정보</h2><div class="result-score">${correct()}<small style="font-size:20px"> / ${questions.length}</small></div><p>${answered()}문제 풀이 · 복습 대기 ${pending().length}문제</p><div class="actions" style="justify-content:center"><a class="btn secondary" href="#home">대시보드</a><a class="btn" href="#review">오답 복습하기 →</a></div></section>`;return heading('배운 내용을 내 것으로.',`단원 확인 문제 ${questions.length}개 · 정답 확인 후 해설을 읽어보세요.`)+questionCard(questions[state.quizIndex],'quiz');}
function review(){if(reviewId)return heading('다시 풀며, 더 단단하게.','정답을 맞히면 오답 노트에 복습 완료로 기록됩니다.')+questionCard(questions.find(q=>q.id===reviewId),'review');return heading('틀린 문제에서 실력이 자라요.','첫 풀이에서 틀린 문제와 복습 완료 기록을 모았어요.')+`<div class="section-title"><h2>복습 대기 ${pending().length}문제</h2><span>복습 완료 ${state.resolved.length}문제</span></div>${!state.wrong.length?`<section class="panel empty"><div class="symbol">✓</div><h2>아직 모인 오답이 없어요.</h2><p class="muted">${answered()?'지금까지 잘하고 있어요. 다음 문제도 도전해 보세요.':'단원 문제를 풀면 틀린 문제가 이곳에 자동으로 저장됩니다.'}</p><a class="btn" href="#quiz">문제 풀러 가기 →</a></section>`:state.wrong.map(id=>{const q=questions.find(q=>q.id===id),done=state.resolved.includes(id);return `<article class="panel review-item"><div class="section-title"><span class="pill">${done?'✓ 복습 완료':'↻ 복습 대기'} · ${lessons[q.lesson].title}</span><span>문제 ${questions.indexOf(q)+1}</span></div><h3>${q.text}</h3><p class="muted">첫 선택: ${q.options[state.answers[id]]}</p><button class="btn ${done?'secondary':''}" data-review="${id}">${done?'다시 연습하기':'정답 가리고 재풀이'} →</button></article>`;}).join('')}`;}
function route(){const name=location.hash.slice(1);return ['learn','quiz','review'].includes(name)?name:'home';}
function render(){if(!lessons.length){main.innerHTML='<section class="panel" role="status">학습 콘텐츠를 불러오는 중입니다.</section>';return;}const r=route();main.innerHTML=(!storageOK?'<div class="notice">브라우저 저장소를 사용할 수 없어 기록이 현재 탭에서만 유지됩니다.</div>':'')+({home,learn,quiz,review}[r])();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===r));document.getElementById('breadcrumb').textContent={home:'대시보드',learn:'개념 학습',quiz:'문제 풀이',review:'오답 노트'}[r];document.getElementById('wrong-badge').textContent=pending().length;updateSaveStatus();}
main.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.lesson!==undefined){state.lesson=+b.dataset.lesson;persist();}else if(b.dataset.choice!==undefined){selected=+b.dataset.choice;}else if(b.dataset.concept!==undefined){state.lesson=+b.dataset.concept;persist();location.hash='learn';return;}else if(b.dataset.review){reviewId=b.dataset.review;reviewResult=null;selected=null;}else{switch(b.dataset.action){case 'prev':state.lesson=Math.max(0,state.lesson-1);persist();break;case 'complete':if(!state.completed.includes(state.lesson))state.completed.push(state.lesson);if(state.lesson<lessons.length-1)state.lesson++;else{persist();location.hash='quiz';return;}persist();break;case 'submit':{if(selected===null)return;const q=questions[state.quizIndex];if(q.id in state.answers)return;state.answers[q.id]=selected;if(selected!==q.answer&&!state.wrong.includes(q.id))state.wrong.push(q.id);persist();selected=null;break;}case 'previous-question':state.quizIndex=Math.max(0,state.quizIndex-1);selected=null;persist();break;case 'next':if(state.quizIndex<questions.length-1)state.quizIndex++;else quizSummary=true;selected=null;persist();break;case 'review-submit':{if(selected===null)return;const q=questions.find(q=>q.id===reviewId);reviewResult=selected;if(selected===q.answer&&!state.resolved.includes(q.id))state.resolved.push(q.id);persist();break;}case 'review-list':reviewId=null;reviewResult=null;selected=null;break;}}render();});
window.addEventListener('hashchange',()=>{selected=null;reviewId=null;reviewResult=null;quizSummary=false;render();window.scrollTo(0,0);main.focus({preventScroll:true});});
document.getElementById('reset').addEventListener('click',()=>{if(confirm('현재 학습 기록의 개념 진도, 답안, 오답을 모두 초기화할까요?')){state=fresh();selected=null;reviewId=null;reviewResult=null;quizSummary=false;persist();render();}});
function installContent(data){
  if(!data||!Array.isArray(data.lessons)||!data.lessons.length||!Array.isArray(data.questions)||!data.questions.length)throw Error('사용할 수 있는 개념 또는 문제가 없습니다.');
  lessons=data.lessons;questions=data.questions;
  try{state=sanitize(JSON.parse(localStorage.getItem(KEY)));}catch{storageOK=false;state=fresh();}
  render();
}
async function loadContent(){
  try{const response=await fetch('/api/content',{cache:'no-store'});if(!response.ok)throw Error('콘텐츠를 불러올 수 없습니다.');installContent(await response.json());return true;}
  catch{main.innerHTML='<section class="panel"><h2>학습 콘텐츠에 연결하지 못했습니다.</h2><p>프로젝트 폴더에서 npm start 실행 후 http://127.0.0.1:4173 으로 접속하고 새로고침해 주세요.</p></section>';return false;}
}
render();
if(typeof fetch==='function')window.contentReady=loadContent();
